// Content lookup: returns the frozen entry or null if the triple is not in
// the registry (e.g. an axisId, domain, or band that doesn't exist).
function getAlignmentEntry(axisId, domain, band) {
  const found = ALIGNMENT_LIBRARY_REGISTRY.find(
    (e) => e.axisId === axisId && e.domain === domain && e.band === band
  );
  return found || null;
}

// Deterministic per-domain salience selector, per Lyra's ruled policy
// (2026-08-01, B-4 Round 34/35): among a caller-supplied candidate-axis
// set, select the axis with the largest distance from the scale midpoint
// (4 on the belief-map instrument's 1-7 scale), convert its score to the
// standard five bands via the caller-supplied band classifier, and apply
// a fixed tie-break priority when two candidates are equally salient.
//
// This function does NOT hardcode which axes are candidates for which
// domain (Work/Relationships/Decisions/Conflict) - that assignment is a
// separate, still-open product decision (vault doc open question 3).
// Callers supply candidateAxisIds explicitly. No new scoring logic: score
// classification is delegated to classifyBand, matching
// lib/belief-map-registry.js's BAND_THRESHOLDS so no duplicate threshold
// constants can drift from that module.
//
// scoresByAxisId: { [axisId]: number } - existing axis scores, already computed.
// classifyBand: (score: number) => bandKey - e.g. belief-map-registry's
//   own band classifier, so thresholds live in exactly one place.
// tieBreakPriority: array of axisIds in priority order, used only when two
//   or more candidates tie exactly on distance from midpoint.
function selectAlignmentAxis(candidateAxisIds, scoresByAxisId, classifyBand, tieBreakPriority) {
  if (!Array.isArray(candidateAxisIds) || candidateAxisIds.length === 0) {
    throw new Error('selectAlignmentAxis: candidateAxisIds must be a non-empty array');
  }
  const MIDPOINT = 4;
  let best = null, bestDistance = -Infinity;
  for (const axisId of candidateAxisIds) {
    const score = scoresByAxisId[axisId];
    if (typeof score !== 'number') continue;
    const distance = Math.abs(score - MIDPOINT);
    if (distance > bestDistance) {
      best = axisId;
      bestDistance = distance;
    } else if (distance === bestDistance && best !== null) {
      const priority = Array.isArray(tieBreakPriority) ? tieBreakPriority : candidateAxisIds;
      if (priority.indexOf(axisId) !== -1 && priority.indexOf(axisId) < priority.indexOf(best)) {
        best = axisId;
      }
    }
  }
  if (best === null) return null;
  const band = classifyBand(scoresByAxisId[best]);
  return { axisId: best, band, score: scoresByAxisId[best] };
}

module.exports = {
  REGISTRY_SCHEMA_VERSION,
  AXIS_IDS,
  DOMAINS,
  BAND_KEYS,
  ALIGNMENT_LIBRARY_REGISTRY,
  getAlignmentEntry,
  selectAlignmentAxis,
};
